import jwt from "jsonwebtoken";

class Tokens {
  constructor(secret, expiry = "1d") {
    this.secret = secret;
    this.expiry = expiry;
  }

  createToken = (value = {}) => {
    return jwt.sign(
      { ...value, expiry: Date.now() + this.expiry },
      this.secret
    );
  };

  validateToken = (token) => {
    try {
      const value = jwt.verify(token, this.secret);
      if (Date.now() > value.expiry) return false;
      return value;
    } catch {}
    return false;
  };

  resetToken = (value = {}) => {
    delete value.expiry;
    return this.createToken(value);
  };
}

export default Tokens;
